\newcommand{\Q}{\mathbb{Q}}
\newcommand{\F}{\mathbb{F}}
\newcommand{\Gal}{\mathrm{Gal}}
\newcommand{\fp}[3]{#1\times_{#3}#2}

\title[The Dial-Overlap Law]{The Dial-Overlap Law: Fields Sharing a Galois Quotient\\ Are Redundant by Exactly Its Entropy}
\author{Aristotle}
\date{2026-10-08}

\begin{document}

\begin{abstract}
Attach to each number field a \emph{dial}: the map sending an unramified prime $p$ to its splitting type (equivalently, the conjugacy class of its Frobenius). By the Chebotarev density theorem the Frobenius pair of a prime in two fields $L_1,L_2$ is equidistributed on $\Gal(L_1L_2/\Q)$. When $L_1$ and $L_2$ share a Galois subfield with group $C$, this group is the fibre product $\fp GHC$. We study the mutual information between the two dials in the resulting uniform model.

We prove an \emph{abstract overlap law}. On a finite uniform sample space, if two readouts both determine a label $\kappa$ and are independent on every fibre of $\kappa$, their mutual information equals $H(\kappa)$ exactly. Fibrewise independence alone already bounds it by $H(\kappa)$. Fibre products satisfy fibrewise independence automatically. This gives the \emph{Overlap Law}: readouts that determine the shared character share exactly $\log_2|C|$ bits, and no readouts share more. The case $|C|=2$ is the \emph{Partial-Overlap Law}: two fields sharing a quadratic subfield are exactly one bit redundant, whatever their Galois groups.

For $S_3$ the compositum group has order $18$, the joint splitting-type table is $1:2:2:4:9$, and type agreement is $7/9$, made up of $9/9$ on the inert fibre and $5/9$ on the split fibre. This completes a three-rung ladder: coprime ($0$ bits), shared quadratic subfield ($1$ bit), same field ($\tfrac23+\tfrac12\log_23$ bits). Sign-level mutual information cannot distinguish partial overlap from identity, whereas type agreement can. Further results cover $S_n\times_{C_2}S_m$, cyclic quartic pairs, and three dials over a common subfield (total correlation $2\log_2|C|$, co-information $+\log_2|C|$). Experiments on all primes $7<p<60000$ agree with every prediction to within finite-sample error.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Prime dials}
Let $f\in\mathbb{Z}[x]$ be an irreducible cubic whose splitting field $L$ has $\Gal(L/\Q)\cong S_3$. For a prime $p\nmid\operatorname{disc}(f)$, the number of roots of $f$ modulo $p$ is $3$, $1$ or $0$. Correspondingly $p$ has splitting type $111$, $12$ or $3$, and its Frobenius class in $S_3$ is the identity, a transposition, or a $3$-cycle. By Chebotarev the dial shows $111,3,12$ with frequencies $1/6,2/6,3/6$, and carries entropy
\[
H(T)=\tfrac16\log_26+\tfrac13\log_23+\tfrac12\log_22=\tfrac23+\tfrac12\log_23\approx1.4591\text{ bits}.
\]

\subsection{The open cell}
Read two dials on the same prime. If the splitting fields are linearly disjoint, the Frobenius pair is uniform on $S_3\times S_3$ and the dials are independent. If the cubics define the same field, the dials share the full $H(T)$. The open cell between these consists of genuinely different $S_3$ fields that share their quadratic resolvent field $\Q(\sqrt d)$. A scan of $56{,}410$ $S_3$ cubics produced two such pairs:
\begin{center}
\begin{tabular}{ccccc}\toprule
$d$ & cubic 1 & disc & cubic 2 & disc\\\midrule
$-7$ & $x^3-5x-5$ & $-175=-7\cdot5^2$ & $x^3-3x-5$ & $-567=-7\cdot9^2$\\
$-3$ & $x^3-6x-6$ & $-108=-3\cdot6^2$ & $x^3-3$ & $-243=-3\cdot9^2$\\\bottomrule
\end{tabular}
\end{center}
Measured deficits relative to full redundancy were $+0.9998$, $+0.9998$ and $+1.0000$ bits. We explain why the answer is exactly one bit. Note that discriminant \emph{values} are not field invariants: $-175$ and $-567$ define the same quadratic field because they differ by a square factor. The relevant object is $\Q(\sqrt{\operatorname{disc}})$, not the integer.

\section{The counting-entropy framework}
Throughout, $s$ is a non-empty finite set with the uniform measure, and a \emph{readout} is any function on $s$. Logarithms are base $2$.

\begin{definition}
For $g:s\to B$ with fibres $s_b=g^{-1}(b)$, the entropy is
\[
H_s(g)=-\sum_b\frac{|s_b|}{|s|}\log\frac{|s_b|}{|s|}=\log|s|-\frac1{|s|}\sum_{x\in s}\log|s_{g(x)}|.
\]
For a label $\kappa$ with fibres $s^c$ define $H_s(g\mid\kappa)=\sum_c\frac{|s^c|}{|s|}H_{s^c}(g)$, and set $I_s(g;k)=H_s(g)-H_s(g\mid k)$.
\end{definition}

We use the chain rule $H(g\mid k)=H(g,k)-H(k)$, non-negativity of $I$, the data-processing inequality $I(\phi\circ g;k)\le I(g;k)$, and the product rule for readouts of different coordinates of $A\times B$.

\begin{definition}
A readout $g$ \emph{determines} $\kappa$ on $s$ if $g(x)=g(y)$ implies $\kappa(x)=\kappa(y)$. Readouts $g,k$ are \emph{fibrewise independent given $\kappa$} if $H_{s^c}(g,k)=H_{s^c}(g)+H_{s^c}(k)$ for every $c$.
\end{definition}

\section{The abstract overlap law}

\begin{lemma}[Chain rule along a determined label]\label{lem:chain}
If $g$ determines $\kappa$, then $H(g)=H(\kappa)+H(g\mid\kappa)$.
\end{lemma}
\begin{proof}
The readouts $(g,\kappa)$ and $g$ have the same fibres, so $H(g,\kappa)=H(g)$. Apply the chain rule.
\end{proof}

\begin{lemma}\label{lem:split}
If $g,k$ are fibrewise independent given $\kappa$, then $H((g,k)\mid\kappa)=H(g\mid\kappa)+H(k\mid\kappa)$.
\end{lemma}
\begin{proof}
Compare the two sides fibre by fibre.
\end{proof}

\begin{theorem}[Abstract Overlap Law]\label{thm:abstract}
If $g$ and $k$ both determine $\kappa$ and are fibrewise independent given $\kappa$, then $I(g;k)=H(\kappa)$.
\end{theorem}
\begin{proof}
The pair $(g,k)$ also determines $\kappa$. Lemma~\ref{lem:chain} applied to $g$, to $k$ and to $(g,k)$, together with Lemma~\ref{lem:split}, gives
$I(g;k)=H(g)+H(k)-H(g,k)=2H(\kappa)-H(\kappa)=H(\kappa)$.
\end{proof}

\begin{theorem}[Overlap Ceiling]\label{thm:ceiling}
If $g,k$ are fibrewise independent given $\kappa$, then $I(g;k)\le H(\kappa)$, whether or not they determine $\kappa$.
\end{theorem}
\begin{proof}
The augmented readouts $\tilde g=(g,\kappa)$ and $\tilde k=(k,\kappa)$ determine $\kappa$ and remain fibrewise independent, so $I(\tilde g;\tilde k)=H(\kappa)$ by Theorem~\ref{thm:abstract}. Since $g$ and $k$ are coarsenings of $\tilde g$ and $\tilde k$, data processing gives $I(g;k)\le I(\tilde g;\tilde k)$.
\end{proof}

\begin{lemma}\label{lem:balanced}
If every fibre of $\kappa$ meeting $s$ has size $|s|/m$, then $H(\kappa)=\log m$.
\end{lemma}

\section{Fibre products}

\begin{definition}
For finite groups and homomorphisms $\chi_1:G\to C$, $\chi_2:H\to C$, set
$\fp GHC=\{(g,h):\chi_1(g)=\chi_2(h)\}$.
\end{definition}

\emph{Arithmetic meaning.} Let $L_1$ and $L_2$ be Galois over $\Q$ with groups $G$ and $H$, and suppose $L_1\cap L_2$ is Galois with group $C$, with $\chi_i$ the (surjective) restriction maps. Then $\Gal(L_1L_2/\Q)\cong\fp GHC$, and by Chebotarev the Frobenius pair of an unramified prime is equidistributed there. These two facts are the only arithmetic inputs. Everything else is exact finite combinatorics.

\begin{proposition}[Fibres are products]\label{prop:fibres}
For each $c\in C$, $\{(g,h)\in\fp GHC:\chi_1(g)=c\}=\chi_1^{-1}(c)\times\chi_2^{-1}(c)$. Hence any readouts $T_1(g)$ and $T_2(h)$ are fibrewise independent given the shared character, and have zero mutual information on every fibre.
\end{proposition}

\begin{proposition}[Order formula]\label{prop:order}
If $\chi_1$ and $\chi_2$ are surjective, each value of the shared character occupies $|\ker\chi_1||\ker\chi_2|$ elements. Hence $|C|\cdot|\fp GHC|=|G|\cdot|H|$, and the shared character carries $\log|C|$ bits.
\end{proposition}
\begin{proof}
Each fibre of a surjection is a coset of the kernel. Combine Proposition~\ref{prop:fibres} with Lemma~\ref{lem:balanced}.
\end{proof}

\begin{theorem}[The Overlap Law]\label{thm:overlap}
Let $\chi_1,\chi_2$ be surjective. If $T_1$ and $T_2$ determine the character, meaning $\chi_i=f_i\circ T_i$, then on $\fp GHC$
\[
I(T_1;T_2)=\log_2|C|.
\]
For arbitrary readouts, $0\le I(T_1;T_2)\le\log_2|C|$.
\end{theorem}
\begin{proof}
Take $\kappa(g,h)=\chi_1(g)$ and apply Theorems~\ref{thm:abstract} and~\ref{thm:ceiling}, Proposition~\ref{prop:fibres} and Proposition~\ref{prop:order}.
\end{proof}

\begin{corollary}[Partial-Overlap Law]
If $|C|=2$, character-determining readouts share exactly one bit, for arbitrary finite $G$ and $H$, and no readouts share more.
\end{corollary}

\begin{corollary}
For all $n,m\ge2$, cycle types on $S_n\times_{C_2}S_m$ (both maps the sign) share exactly one bit.
\end{corollary}

\section{The overlap ladder}
\begin{theorem}
Let $\chi_1,\chi_2$ be surjective. (i) If $C$ is trivial, every pair of readouts has $I=0$. (ii) In general $0\le I\le\log|C|$, with equality on the right for character-determining readouts. (iii) On the diagonal $G\times_GG$, the full Frobenius readouts share $\log|G|$ bits.
\end{theorem}

\section{The $S_3$ pairs}
\begin{theorem}\label{thm:s3}
On $S_3\times_{C_2}S_3$, a group of order $18$, the joint splitting-type table is
\begin{center}
\begin{tabular}{cccc}\toprule
 & $T_2=111$ & $T_2=3$ & $T_2=12$\\\midrule
$T_1=111$ & 1 & 2 & 0\\
$T_1=3$ & 2 & 4 & 0\\
$T_1=12$ & 0 & 0 & 9\\\bottomrule
\end{tabular}
\end{center}
Moreover: $I(T_1;T_2)=1$, with $H(T_1)=1.4591$ and $H(T_1\mid T_2)=0.4591$. Type agreement is $14/18=7/9$ and off-diagonal mass is $2/9$. Agreement is $9/9$ on the fibre $\chi=-1$ and $5/9=(1/3)^2+(2/3)^2$ on the fibre $\chi=+1$, which is $A_3\times A_3$. The fibrewise mutual information is $0$.
\end{theorem}

\begin{proposition}
On $S_3\times S_3$ we have $I=0$ and agreement $7/18$. On the diagonal, $I=H(T)=\tfrac23+\tfrac12\log_23$ and agreement is $1$.
\end{proposition}

\begin{theorem}[Sign is blind, type discriminates]
The sign readouts share exactly $1$ bit on both $S_3\times_{C_2}S_3$ and the diagonal. In contrast, type agreement is $14/18$ versus $6/6$, and full-type mutual information is $1$ versus $\tfrac23+\tfrac12\log_23$.
\end{theorem}

\begin{remark}
The decomposition $1.5-0.5$ belongs to the cyclic quartic pair below. For $S_3$ it reads $1.4591-0.4591$.
\end{remark}

\section{Cyclic quartic pairs}
\begin{theorem}
On $C_4\times_{C_2}C_4$ (order $8$), with residue degree equal to the order of Frobenius,
$H(\deg_1)=\tfrac32$, $H(\deg_1\mid\deg_2)=\tfrac12$ and $I(\deg_1;\deg_2)=1$.
\end{theorem}

\section{Three dials}
\begin{theorem}
Let $T_1,T_2,T_3$ determine the character on $G\times_CH\times_CK=\{(g,h,k):\chi_1(g)=\chi_2(h)=\chi_3(k)\}$. Then every pairwise mutual information equals $\log|C|$ and $I(T_1;(T_2,T_3))=\log|C|$. The total correlation $H(T_1)+H(T_2)+H(T_3)-H(T_1,T_2,T_3)$ equals $2\log|C|$, and the co-information $I(T_1;T_2)+I(T_1;T_3)-I(T_1;(T_2,T_3))$ equals $+\log|C|$.
\end{theorem}
\begin{proof}
Each fibre of $\kappa=\chi_1(g)$ is a triple product, and every readout considered determines $\kappa$. Apply Theorem~\ref{thm:abstract}, and use $\mathrm{TC}=I(T_1;(T_2,T_3))+I(T_2;T_3)$.
\end{proof}
For three $S_3$ cubics with a common quadratic resolvent this gives $2$ bits and $+1$ bit.

\section{Algorithms and experiments}
For $p\nmid\operatorname{disc}(f)$ the number of roots of $f$ in $\F_p$ is $\deg\gcd(x^p-x,f)$, computed by repeated squaring modulo $(f,p)$ in $O(\log p)$ steps. Exact entropies on $\fp GHC$ cost $O(|G||H|/|C|)$. For $S_n\times_{C_2}S_m$ with $2\le n\le m\le5$, all ten cases return exactly $1$ bit.

The table below uses all primes $7<p<60000$ unramified in both cubics.
\begin{center}
\begin{tabular}{lccccc}\toprule
Pair & $n$ & $\hat I$ & law & agreement & law\\\midrule
$x^3-5x-5$ \& $x^3-3x-5$ & 6053 & 1.0000 & 1 & 0.7816 & 0.7778\\
$x^3-6x-6$ \& $x^3-3$ & 6053 & 1.0000 & 1 & 0.7785 & 0.7778\\
$x^3+x+1$ \& $x^3-x-1$ & 6051 & 0.0001 & 0 & 0.3889 & 0.3889\\
$x^3-5x-5$ twice & 6053 & 1.4559 & 1.4591 & 1 & 1\\\bottomrule
\end{tabular}
\end{center}
For $d=-7$ the observed table is $329,664,658,1369,3033$, with all structurally-zero cells empty. The law predicts $336,673,673,1345,3027$. In the original larger simulation the off-diagonal mass was $34{,}375$ against $34{,}307$ predicted. A coprime control reproduced the coprime-synergy statistic of earlier work ($0.1300$ versus $0.1290$).

The plug-in estimator is biased upward by roughly $(|B_1|-1)(|B_2|-1)/(2n\ln2)$. At about $2$ samples per cell this is about half a bit. The $S_3$ shared-subfield table has only five non-zero cells, so bias is negligible here. Large sparse joints need about $100$ samples per cell or explicit bias modelling.

\section{Discussion and future work}
The redundancy between two number fields seen through Frobenius readouts is the entropy of their shared Galois quotient. It is attained by readouts that see that quotient and never exceeded. The ``correlation confined to the residue-invisible fibre'' is in fact a zero-correlation statement. The arithmetic enters only through the fibre-product identification and Chebotarev equidistribution.

Open directions:
(1) non-abelian shared quotients, where class readouts should share $H(\text{class in }Q)$;
(2) $n$ dials, with conjectured total correlation $(n-1)\log|C|$ and co-information $+\log|C|$;
(3) inclusion--exclusion over lattices of distinct shared subfields;
(4) bias laws stated in terms of the number of structurally non-zero cells.

\end{document}

