"""Convergence of plug-in mutual information over real primes for the four cubic pairs."""
from __future__ import annotations
import math
from collections import Counter
import matplotlib.pyplot as plt

def primes_below(n: int) -> list[int]:
    s = bytearray([1]) * n; s[0:2] = b"\x00\x00"
    for i in range(2, int(n ** .5) + 1):
        if s[i]: s[i * i::i] = bytearray(len(range(i * i, n, i)))
    return [i for i in range(n) if s[i]]

def mulmod(a: list[int], b: list[int], f: list[int], p: int) -> list[int]:
    r = [0] * 5
    for i in range(3):
        for j in range(3): r[i + j] = (r[i + j] + a[i] * b[j]) % p
    for d in (4, 3):
        c = r[d]
        if c:
            for k in range(3): r[d - 3 + k] = (r[d - 3 + k] - c * f[k]) % p
    return r[:3]

def gcd_deg(a: list[int], b: list[int], p: int) -> int:
    def tr(v: list[int]) -> list[int]:
        v = [x % p for x in v]
        while v and v[-1] == 0: v.pop()
        return v
    a, b = tr(a), tr(b)
    while b:
        inv = pow(b[-1], p - 2, p)
        while a and len(a) >= len(b):
            c, sh = a[-1] * inv % p, len(a) - len(b)
            for i, y in enumerate(b): a[i + sh] = (a[i + sh] - c * y) % p
            a = tr(a)
        a, b = b, a
    return len(a) - 1

def ftype(f: list[int], p: int) -> int:
    r, base, e = [1, 0, 0], [0, 1, 0], p
    while e:
        if e & 1: r = mulmod(r, base, f, p)
        base = mulmod(base, base, f, p); e >>= 1
    return gcd_deg([r[0], (r[1] - 1) % p, r[2]], f + [1], p)

def ent(c: Counter) -> float:
    n = sum(c.values()); return -sum(v / n * math.log2(v / n) for v in c.values())

pairs = {"d=-7 shared": ([-5, -5, 0], [-5, -3, 0], 175 * 567, 1.0),
         "d=-3 shared": ([-6, -6, 0], [-3, 0, 0], 108 * 243, 1.0),
         "coprime": ([1, 1, 0], [-1, -1, 0], 31 * 23, 0.0),
         "same field": ([-5, -5, 0], [-5, -5, 0], 175, 2 / 3 + math.log2(3) / 2)}
ps = [p for p in primes_below(60000) if p > 7]
fig, ax = plt.subplots(figsize=(9, 5.5))
for (name, (f, g, D, law)), col in zip(pairs.items(), ["#3f51b5", "#009688", "#ff7043", "#8e24aa"]):
    data = [(ftype(f, p), ftype(g, p)) for p in ps if D % p]
    xs, ys = [], []
    for n in range(50, len(data) + 1, 50):
        d = data[:n]
        xs.append(n); ys.append(ent(Counter(a for a, _ in d)) + ent(Counter(b for _, b in d)) - ent(Counter(d)))
    ax.plot(xs, ys, color=col, label=f"{name} (law {law:.4f})"); ax.axhline(law, color=col, ls=":", lw=.8)
ax.set_xlabel("number of primes 7 < p used"); ax.set_ylabel("plug-in I(T1;T2) (bits)")
ax.set_title("Real primes converge to the overlap ladder: 0, 1, 1, 1.4591 bits")
ax.legend(); plt.tight_layout(); plt.savefig("primes_convergence.png", dpi=150); plt.show()
